  "book-youcat": { kind: "책", title: "YOUCAT 가톨릭 청년 교리서", by: "오스트리아 주교회의 · 최용호 옮김 · 가톨릭출판사", url: "", note: "가톨릭 청년들이 배우는 내용을 문답으로 정리한 공식 청년 교리서입니다. 가톨릭 친구나 가족이 무엇을 믿는지 그 전통의 말로 알고 싶을 때 봅니다.", tags: ["가톨릭과 개신교", "교사를 위한 자료"] },
  "mag-kids": { kind: "큐티지", title: "어린이복있는사람", by: "총회교육원 · 생명의양식", url: "", note: "초등학교 고학년 어린이의 큐티를 돕는 큐티지입니다. 아이가 혼자 성경을 읽어 보고 싶어 할 때 건넬 수 있습니다.", tags: ["성경 읽기"] },
  "org-112": { kind: "신고", title: "아동학대 신고 112 (아이지킴콜)", by: "경찰 · 국번 없이 112", url: "https://mediahub.seoul.go.kr/archives/1297482", note: "아동학대가 의심되면 112로 신고합니다. 신고에 앞서 상담이 필요하면 보건복지상담센터 129에 물어볼 수 있습니다.", tags: ["위기와 보호"] },
  "org-1388": { kind: "상담", title: "청소년상담 1388", by: "365일 24시간 무료 상담", url: "https://www.bokjiro.go.kr/ssis-tbu/cms/pc/news/promotion/1307645_1118.html", note: "9~24세 청소년과 부모가 전화나 문자(1388), 카카오톡 '청소년상담1388' 채널, 웹(1388.go.kr)으로 상담받을 수 있습니다.", tags: ["위기와 보호"] },
  "org-109": { kind: "상담", title: "자살예방상담전화 109", by: "보건복지부 · 2024년 1월부터 하나로 통합된 번호", url: "https://www.korea.kr/news/policyNewsView.do?newsId=148921684", note: "자살을 생각하는 사람이나 그 곁에 있는 사람이 걸 수 있는 상담 번호입니다. 아이가 위험해 보이면 교사 혼자 판단하지 말고 보호자와 전문가에게 바로 알리세요.", tags: ["위기와 보호"] },
  "art-disclose": { kind: "기사", title: "아이 고백엔 '네가 말해줘서 고마워'부터 말하세요, 신고는 112로", by: "위키트리 · 2026년 11월 · 국가아동권리보장원 등의 안내 인용", url: "https://www.wikitree.co.kr/articles/1171191", note: "아이가 피해를 털어놓을 때 어른이 할 말과 하지 말아야 할 말, 기록과 신고 방법을 정리한 기사입니다. 교사가 먼저 읽어 두면 좋습니다.", tags: ["위기와 보호", "교사를 위한 자료"] },
  "book-women": { kind: "책", title: "여성 리더십 논쟁", by: "새물결플러스 · 스펙트럼 시리즈", url: "", note: "교회 안의 여성 리더십을 두고 서로 다른 입장의 학자들이 각자의 견해를 쓰고 서로 응답하는 책입니다. 교사가 여러 입장을 공정하게 알고 싶을 때 먼저 읽습니다.", tags: ["교사를 위한 자료"] },
  "book-theodicy": { kind: "책", title: "신정론 논쟁", by: "새물결플러스 · 스펙트럼 시리즈", url: "", note: "선하신 하나님과 세상의 악과 고통을 두고 서로 다른 입장의 학자들이 각자의 견해를 쓰고 서로 응답하는 책입니다. 교사가 먼저 읽고 아이 눈높이로 옮겨 주세요.", tags: ["슬픔과 고난", "교사를 위한 자료"] },
  "art-jesa": { kind: "기사", title: "불교·가톨릭 신도들이 명절 차례 지내는 방법", by: "경향신문 · 2011년 1월", url: "https://www.khan.co.kr/article/201101291215251", note: "한국 천주교회가 제사를 어떻게 허용하고 무엇을 금하는지, 가톨릭식 차례 순서를 소개한 기사입니다.", tags: ["가톨릭과 개신교"] },
  "edu-gatekeeper": { kind: "교육", title: "생명지킴이 교육 (자살예방 교육)", by: "지역 자살예방센터 · 서울시 안내 예시", url: "https://news.seoul.go.kr/welfare/archives/561838", note: "주변 사람의 위험 신호를 알아보고 도움으로 잇는 법을 배우는 시민 교육입니다. 교사용 과정도 있습니다. 다른 지역은 시·군·구 자살예방센터에 물어보세요.", tags: ["위기와 보호", "교사를 위한 자료"] },
  "org-cult":  { kind: "기관", title: "한국기독교이단상담소협회 · 교단 이단대책위원회", by: "지역 상담소 연락처는 협회나 교단을 통해 확인", url: "", note: "이단 관련 상담과 회복을 돕습니다. 교사 혼자 해결하려 하지 말고 부모님과 함께 도움을 요청하세요.", tags: ["요한계시록과 이단"] },
  "org-ieum":  { kind: "기관", title: "이음공동체", by: "2020년 CBS '신천지 OUT' 캠페인을 계기로 출범", url: "", note: "이단 탈퇴자의 상담에서 교회 정착까지를 잇는 공동체입니다.", tags: ["요한계시록과 이단"] },
  "media-hd":  { kind: "매체", title: "현대종교", by: "이단 정보를 다루는 기독교 매체", url: "", note: "이단의 접근 방식과 최근 동향을 확인할 때 참고합니다.", tags: ["요한계시록과 이단"] },
  "book-gaanan": { kind: "책", title: "교회 안 나가는 그리스도인", by: "정재영 · IVP (2015)", url: "", note: "교회를 떠났지만 신앙은 놓지 않은 '가나안 성도'를 설문과 심층 면담으로 살핀 연구서입니다. 청년이 왜 떠나는지, 떠난 뒤 어떻게 믿는지 이해하고 싶은 교사와 교역자에게 좋습니다.", tags: ["교회를 떠나고 싶을 때", "교사를 위한 자료"] },
  "book-bonhoeffer": { kind: "책", title: "성도의 공동생활", by: "디트리히 본회퍼 · 정현숙 옮김 · 복있는사람 (2016)", url: "", note: "고백교회의 신학교 공동체를 이끈 본회퍼가 그리스도인이 함께 사는 삶을 쓴 고전입니다. 실망스러운 공동체를 어떻게 바라볼지, 공동체가 왜 선물인지 생각하게 합니다.", tags: ["교회를 떠나고 싶을 때", "교사를 위한 자료"] },
  "book-rediscover": { kind: "책", title: "교회의 재발견", by: "콜린 핸슨 · 조너선 리먼 · 개혁된실천사", url: "", note: "온라인 예배가 늘고 교회 출석이 줄어든 시대에, 그리스도인에게 왜 지역 교회가 필요한지 설명하는 책입니다.", tags: ["교회를 떠나고 싶을 때"] },
  "art-bridge": { kind: "기사", title: "“그냥 교회에 얌전히 앉아 있었죠” 무너진 신앙 계승, 가정에 답있다", by: "국민일보 · 2025년 5월 · 기획 '믿음의 다리를 잇다'", url: "https://v.daum.net/v/20250514170308988", note: "자녀가 조용히 교회를 떠나는 현실과 가정의 신앙 대화를 다룬 기획 기사입니다. 부모와 신앙 이야기를 자주 나눈다는 교회 출석 청소년이 12%에 그쳤다는 조사를 소개합니다.", tags: ["교회를 떠나고 싶을 때", "교사를 위한 자료"] }
