function agesOf(id) {
  const f = (META[id] || {}).f || "", s = new Set();
  if (/누구나/.test(f)) ["kid", "teen", "adult", "teacher"].forEach(a => s.add(a));
  if (/초등/.test(f)) s.add("kid");
  if (/초등.*~|중고등|고등|청소년/.test(f)) s.add("teen");
  if (/청년|어른|~/.test(f)) s.add("adult");
  if (/교사|교역자|부모/.test(f)) s.add("teacher");
  return s;
}

